mapper.select:
SELECT oi.id, oi.create_time, oi.update_time as updateTime, oi.create_user_name, oi.create_user_id, oi.update_user_name, oi.update_user_id, oi.version, oi.is_deleted, oi.warehouse_code, oi.dict_platform, oi.platform_sku, oi.platform_sku_name, oi.product_name, oi.sku_no, oi.sku_id, oi.deliver_onway_qty as deliverOnwayQty, oi.pending_qty as pendingQty, oi.sellable_qty as sellableQty, oi.unsellable_qty as unsellableQty, oi.reserved_qty as reservedQty, oi.onway_qty as onwayQty, oi.lack_qty as lackQty, oi.frozen_qty as frozenQty, oi.shipped_qty as shippedQty, oi.download_time as downloadTime, CASE WHEN oi.dict_platform = 'AliExpress' THEN w.warehouseName WHEN oi.dict_platform = 'fbt' THEN oi.name ELSE opw.warehouse_name END AS NAME, oi.sale_return_in_transit_qty as saleReturnInTransitQty FROM overseas_inventory AS oi LEFT JOIN overseas_provider_warehouse AS opw ON oi.overseas_provider_id = opw.main_id and opw.platform_warehouse_code = oi.warehouse_code AND opw.is_deleted = FALSE AND opw.disabled =FALSE LEFT JOIN overseas_provider AS op ON op.ID = oi.overseas_provider_id AND op.is_deleted = FALSE LEFT JOIN ( SELECT w.NAME AS warehouseName, wm.NAME AS thirdWarehouseName FROM warehouse w INNER JOIN warehouse_mapping wm ON w.ID = wm.warehouse_id AND wm.is_deleted = FALSE WHERE w.is_deleted = FALSE AND wm.dict_Platform = 'AliExpress') as w on oi.NAME = w.thirdWarehouseName and oi.dict_platform = 'AliExpress'
AND oi.id IN
#{id}

select id,warehouse_code, dict_platform,name,platform_sku,platform_sku_name,product_name,sku_no,sku_id,deliver_onway_qty, pending_qty,sellable_qty,unsellable_qty,reserved_qty,onway_qty,lack_qty,frozen_qty,shipped_qty,download_time from overseas_inventory where is_deleted = false
and platform_sku = #{query.platformSku}
and sku_id in
#{item}
and warehouse_code in
#{item}
ORDER BY sellable_qty desc
